def count_sphenic(limit: int) -> int:
    if limit < 1:
        return 0

    # Sieve to find smallest prime factor for each number up to limit
    spf = list(range(limit + 1))
    for i in range(2, int(limit**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i

    count = 0
    for n in range(1, limit + 1):
        # Factorize using spf and check for exactly three distinct primes
        x = n
        primes = set()
        while x > 1:
            p = spf[x]
            primes.add(p)
            if len(primes) > 3:
                break
            while x % p == 0:
                x //= p
        if len(primes) == 3 and x == 1:
            # Ensure no repeated factors by checking product of distinct primes equals n
            prod = 1
            for p in primes:
                prod *= p
            if prod == n:
                count += 1

    return count
