def format_and_validate(records):
    if not records:
        return ""

    name_pattern = re.compile(r"^[A-Za-z\s\-']+$")
    local_pattern = re.compile(r"^[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9])?$")
    domain_label_pattern = re.compile(r"^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$")

    results = []

    for i, record in enumerate(records):
        valid = True

        # Validate name
        name = record.get('name')
        if not isinstance(name, str) or not name.strip() or not name_pattern.match(name):
            valid = False

        # Validate email
        email = record.get('email')
        if valid:
            if not isinstance(email, str) or '@' not in email:
                valid = False
            else:
                parts = email.split('@')
                if len(parts) != 2:
                    valid = False
                else:
                    local, domain = parts
                    if not local_pattern.match(local):
                        valid = False
                    else:
                        labels = domain.split('.')
                        if len(labels) < 2:
                            valid = False
                        else:
                            for label in labels:
                                if not label or not domain_label_pattern.match(label):
                                    valid = False
                                    break

        # Validate age
        age = record.get('age')
        if valid:
            if not isinstance(age, int) or isinstance(age, bool) or not (0 <= age <= 150):
                valid = False

        if valid:
            results.append(f"Name: {name}, Email: {email}, Age: {age}")
        else:
            results.append(f"Invalid record: {i}")

    return "\n".join(results)
