def format_and_validate(fmt: str, values: dict) -> str:
    result = []
    i = 0
    n = len(fmt)

    while i < n:
        ch = fmt[i]
        if ch == '{':
            if i + 1 < n and fmt[i + 1] == '{':
                result.append('{')
                i += 2
                continue

            # Find closing brace
            j = i + 1
            while j < n and fmt[j] != '}':
                j += 1
            if j >= n:
                raise ValueError('invalid field')

            field = fmt[i+1:j]

            # Validate field name
            if not field or not field.isidentifier() or not all(c.isascii() for c in field):
                raise ValueError('invalid field')

            if field not in values:
                raise KeyError(field)

            val = values[field]
            if not isinstance(val, (int, str)):
                raise TypeError('bad type')

            result.append(str(val))
            i = j + 1

        elif ch == '}':
            if i + 1 < n and fmt[i + 1] == '}':
                result.append('}')
                i += 2
            else:
                raise ValueError('invalid field')

        else:
            result.append(ch)
            i += 1

    return ''.join(result)
