def parse_log_blocks(text: str) -> dict:
    result = {}
    blocks = text.split('\n---\n')

    # Handle the case where '---' might be at start/end or with different surrounding newlines
    # Re-split more robustly by lines
    lines = text.split('\n')
    current_block_lines = []
    all_blocks = []

    for line in lines:
        if line == '---':
            all_blocks.append(current_block_lines)
            current_block_lines = []
        else:
            current_block_lines.append(line)
    all_blocks.append(current_block_lines)

    for block_lines in all_blocks:
        # Filter out empty lines
        non_empty = [ln for ln in block_lines if ln.strip() != '']
        if not non_empty:
            continue

        header_line = non_empty[0]
        if not header_line.startswith('# '):
            raise ValueError(f"Block does not start with a header: {header_line!r}")

        header = header_line[2:].strip()
        entries = {}

        for entry_line in non_empty[1:]:
            if '=' not in entry_line:
                raise ValueError(f"Malformed entry line (missing '='): {entry_line!r}")
            key, value = entry_line.split('=', 1)
            if key == '':
                raise ValueError(f"Empty key in entry line: {entry_line!r}")
            if any(c.isspace() for c in key):
                raise ValueError(f"Key contains whitespace: {key!r}")
            entries[key] = value

        result[header] = entries

    return result
