def parse_ledger(text: str) -> dict:
    # Parse lines into (indent_width, key, value_or_None)
    entries = []
    for raw in text.splitlines():
        expanded = raw.replace('\t', '    ')
        stripped = expanded.strip()
        if not stripped or stripped.startswith('#'):
            continue
        indent = len(expanded) - len(expanded.lstrip())
        content = expanded[indent:]
        if ' = ' in content:
            key, value = content.split(' = ', 1)
            value = value.strip()
            has_value = True
        else:
            key = content
            value = None
            has_value = False
        key = key.strip()
        if not key or any(ch in key for ch in (' ', '=', '#')):
            raise ValueError(f"Invalid key: {key!r}")
        entries.append((indent, key, value, has_value))

    root = {}
    if not entries:
        return root

    first_indent = entries[0][0]
    if first_indent != 0:
        raise ValueError("First meaningful line must not be indented")

    # Stack of (indent, dict) where stack[-1] is current container
    stack = [(0, root)]
    # Track previous entry info for validation
    prev_indent = None
    prev_had_value = None

    for indent, key, value, has_value in entries:
        if prev_indent is not None:
            if indent > prev_indent:
                # Going deeper: parent must be a section (no value)
                if prev_had_value:
                    raise ValueError(f"Leaf key cannot have children: {key!r}")
                # push parent's dict — it was created when we processed the section key
                # We need to find that dict. The section key's dict was stored... 
                # Actually we handle by pushing at section creation time below.
                pass
            elif indent == prev_indent:
                pass
            else:
                # Dedent: pop until matching indent
                while len(stack) > 1 and stack[-1][0] > indent:
                    stack.pop()
                if stack[-1][0] != indent:
                    raise ValueError(f"Inconsistent indentation at key {key!r}")

        # Determine current container
        current = stack[-1][1]

        if key in current:
            raise ValueError(f"Duplicate key: {key!r}")

        if has_value:
            current[key] = value
        else:
            new_dict = {}
            current[key] = new_dict
            # Push this new section onto stack with its indent
            stack.append((indent, new_dict))

        prev_indent = indent
        prev_had_value = has_value

    return root
