def run_machine(program, inputs):
    state = 'START'
    result = []

    for symbol in inputs:
        matched = False
        for (cur_state, sym, next_state, output) in program:
            if cur_state == state and sym == symbol:
                result.append(output)
                state = next_state
                matched = True
                break
        if not matched:
            result.append('!')
            break

    return ''.join(result)
